import re
from typing import Any, Dict, List, Optional, Tuple

# Helpers provided by the environment
# node_by_title(doc, title) -> node dict or None
# node_by_id(doc, node_id) -> node dict or None
# children(doc, node) -> list of child node ids
# scope_nodes(doc, scope) -> list of node ids that belong to the scope
# table_rows(node) -> iterator yielding (row_index, {col_name: value, ...})
# ---------------------------------------------------------------------------

def _obj_line_mapping(doc: Dict[str, Any], scope: str) -> Dict[str, Tuple[str, int]]:
    """
    Return a mapping from object id (as string) to (node_id, line_index)
    within the Objects list for the given scope.
    """
    mapping = {}
    # find Objects node
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return mapping
    obj_node_id = None
    for child_id in children(doc, scope_node):
        child = node_by_id(doc, child_id)
        if child and child.get("title", "").endswith("Objects"):
            obj_node_id = child.get("node_id", child_id)
            break
    if not obj_node_id:
        return mapping
    obj_node = node_by_id(doc, obj_node_id)
    if not obj_node or obj_node.get("kind") != "list":
        return mapping
    for li, line in enumerate(obj_node.get("lines", [])):
        m = re.match(r"^\s*Object\s+(\d+):\s+(.+)$", line)
        if m:
            oid = m.group(1).strip()
            mapping[oid] = (obj_node_id, li)
    return mapping

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return a list of entity descriptors for the given scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # locate Objects node
    obj_map = _obj_line_mapping(doc, scope)
    entities = []
    for oid, (node_id, li) in obj_map.items():
        # Retrieve full description from the line
        line = node_by_id(doc, node_id).get("lines", [])[li]
        m = re.match(r"^\s*Object\s+(\d+):\s+(.+)$", line)
        desc = m.group(2).strip() if m else ""
        entities.append({
            "id": oid,
            "description": desc,
            "src": [[node_id, li]]
        })
    return entities


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the last frame number recorded for the scope, or None."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None

    motion_node_id = None
    for child_id in children(doc, scope_node):
        child = node_by_id(doc, child_id)
        if child and child.get("title", "").endswith("Motion log"):
            motion_node_id = child.get("node_id", child_id)
            break
    if not motion_node_id:
        return None

    motion_node = node_by_id(doc, motion_node_id)
    if not motion_node or motion_node.get("kind") != "table":
        return None

    last_frame = None
    for row_index, row in table_rows(motion_node):
        frame_val = row.get("frame")
        try:
            f = int(float(frame_val))
            if last_frame is None or f > last_frame:
                last_frame = f
        except Exception:
            continue
    return float(last_frame) if last_frame is not None else None


def _event_details(line: str) -> Optional[Tuple[int, List[str], str]]:
    """Parse an event list line and return frame, object ids, verb."""
    m = re.match(r"^\s*Frame\s+(\d+):\s+(.*)$", line)
    if not m:
        return None
    frame = int(m.group(1))
    rest = m.group(2).strip()
    obj_ids = re.findall(r"Object\s+(\d+)", rest)
    verb = None
    if "enters the scene" in rest:
        verb = "enter"
    elif "in view when the video begins" in rest:
        verb = "view_start"
    elif "exits the scene" in rest:
        verb = "exit"
    elif "collides with" in rest:
        verb = "collide"
    else:
        return None
    return frame, obj_ids, verb


def _collect_events(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all event lines with parsed info and source location."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    events = []
    for child_id in children(doc, scope_node):
        child = node_by_id(doc, child_id)
        if child and child.get("title", "").endswith("Events"):
            ev_node_id = child.get("node_id", child_id)
            for li, line in enumerate(child.get("lines", [])):
                details = _event_details(line)
                if details:
                    frame, obj_ids, verb = details
                    events.append({
                        "frame": frame,
                        "verb": verb,
                        "obj_ids": obj_ids,
                        "src": [[ev_node_id, li]],
                        "full_line": line
                    })
            break
    return events


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return a list of input events for the given scope."""
    events = _collect_events(doc, scope)
    obj_map = _obj_line_mapping(doc, scope)
    inputs = []
    for ev in events:
        if ev["verb"] not in ("enter", "view_start"):
            continue
        for oid in ev["obj_ids"]:
            srcs = ev["src"][:]
            if oid in obj_map:
                srcs.append(obj_map[oid])
            inp = {
                "id": f"inp_{ev['verb']}_{ev['frame']}_{oid}",
                "time": float(ev["frame"]),
                "kind": ev["verb"],
                "entities": [oid],
                "fields": {},
                "src": srcs
            }
            inputs.append(inp)
    return inputs


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return a list of outcome events for the given scope."""
    events = _collect_events(doc, scope)
    obj_map = _obj_line_mapping(doc, scope)
    outcomes = []
    for ev in events:
        if ev["verb"] not in ("exit", "collide"):
            continue
        srcs = ev["src"][:]
        for oid in ev["obj_ids"]:
            if oid in obj_map:
                srcs.append(obj_map[oid])
        out = {
            "time": float(ev["frame"]),
            "kind": ev["verb"],
            "entities": ev["obj_ids"],
            "value": None,
            "src": srcs
        }
        outcomes.append(out)
    return outcomes


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return any constant parameters defined in the scope."""
